import assert from 'node:assert/strict';
import { createHash as enchantProofHash } from 'node:crypto';
function stripEnchantClosedAddition(raw) {
 const digest = x => enchantProofHash('sha256').update(x).digest('hex');
 if(digest(raw)==='d7361af3f4a61e4a6e751e8f4474ec1fbbf2409ddc0fc964e93bd351a75a1e09')return raw;
 assert.equal(digest(raw),'6f2443f87db77dcaf88f565f87c38849c5dde482dc77592102acb64695258dd9','real current 952-key strings authority');
 assert.equal(Object.keys(JSON.parse(raw)).length,952);
 const block=raw.match(/,\n(?: {2}"enchant\.closed\.[^\n]+\n?){8}/gu);
 assert.equal(block?.length,1,'only exact appended eight enchant lines');
 const previous=raw.replace(block[0],'\n');
 assert.equal(digest(previous),'d7361af3f4a61e4a6e751e8f4474ec1fbbf2409ddc0fc964e93bd351a75a1e09','exact bytes restore historical 944 keys');
 return previous;
}
